import 'package:equatable/equatable.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:locallink/core/bloc/bloc_utils.dart';import 'package:locallink/core/models/device.dart';import 'package:locallink/core/models/group.dart';import 'package:locallink/features/groups/domain/group_repository_contract.dart';
final class GroupMembersState extends Equatable{final LocalGroup group;final String localDeviceId;final List<GroupMember> members;final List<Device> devices;final bool isLoading,isWorking;final String? error;const GroupMembersState({required this.group,required this.localDeviceId,this.members=const [],this.devices=const [],this.isLoading=false,this.isWorking=false,this.error});GroupMembersState copyWith({List<GroupMember>? members,List<Device>? devices,bool? isLoading,bool? isWorking,String? error,bool clearError=false})=>GroupMembersState(group:group,localDeviceId:localDeviceId,members:members??this.members,devices:devices??this.devices,isLoading:isLoading??this.isLoading,isWorking:isWorking??this.isWorking,error:clearError?null:(error??this.error));@override List<Object?> get props=>[group,localDeviceId,members,devices,isLoading,isWorking,error];}
final class GroupMembersBloc extends Cubit<GroupMembersState>{final GroupRepositoryContract repository;GroupMembersBloc({required this.repository,required LocalGroup group,required String localDeviceId}):super(GroupMembersState(group:group,localDeviceId:localDeviceId));List<GroupMember> get members=>state.members;List<Device> get devices=>state.devices;bool get isLoading=>state.isLoading;bool get isWorking=>state.isWorking;String? get error=>state.error;bool get isOwner=>state.group.ownerId==state.localDeviceId;List<Device> get addableDevices{final existing=members.map((m)=>m.deviceId).toSet();return devices.where((d)=>!existing.contains(d.id)).toList();}Future<void> load()async{emit(state.copyWith(isLoading:true,clearError:true));try{emit(state.copyWith(members:await repository.listMembers(state.group.id),devices:isOwner?await repository.availableMemberDevices():const [],isLoading:false));}catch(e){emit(state.copyWith(error:cleanBlocError(e),isLoading:false));}}Future<void> addMember(Device device)async{if(!isOwner||state.isWorking)return;emit(state.copyWith(isWorking:true,clearError:true));try{await repository.addMember(state.group.id,device.id);await load();}catch(e){emit(state.copyWith(error:cleanBlocError(e),isWorking:false));rethrow;}finally{emit(state.copyWith(isWorking:false));}}Future<void> removeMember(GroupMember member)async{if(!isOwner||state.isWorking||member.deviceId==state.group.ownerId)return;emit(state.copyWith(isWorking:true,clearError:true));try{await repository.removeMember(state.group.id,member.deviceId);emit(state.copyWith(members:state.members.where((m)=>m.deviceId!=member.deviceId).toList()));}catch(e){emit(state.copyWith(error:cleanBlocError(e)));rethrow;}finally{emit(state.copyWith(isWorking:false));}}}
